 p=argparse.ArgumentParser();p.add_argument('--baseline',type=Path,required=True);p.add_argument('--candidate',type=Path,required=True);p.add_argument('--audit',type=Path,required=True);p.add_argument('--artifacts',type=Path,required=True);p.add_argument('--renderer-report',type=Path,required=True);p.add_argument('--report',type=Path,required=True);p.add_argument('--apply',action='store_true');a=p.parse_args()
 baseline=a.baseline.resolve();candidate=a.candidate.resolve();tools=Path(__file__).resolve().parent;assert baseline!=candidate and not baseline.is_relative_to(candidate) and not candidate.is_relative_to(baseline)
