 catbytes=(baseline/'additions-catalog.json').read_bytes();cat=json.loads(catbytes);newcat=copy.deepcopy(cat);jp={d['id']:d for d in cat['documents'] if d['country']=='JP'}
 audit=json.loads(a.audit.read_text());rr=json.loads(a.renderer_report.read_text());laws=audit['laws'];results=rr['results'];assert audit['passed'] and rr['passed'] and rr['documents']==190
 assert len(jp)==len(laws)==len(results)==190;assert len({d['id'] for d in laws})==len({d['id'] for d in results})==190;assert {d['id'] for d in laws}=={d['id'] for d in results}==set(jp)
