  body=(a.artifacts/(d['id']+'.html')).read_text();r=json.loads((a.artifacts/(d['id']+'.json')).read_text());assert r['htmlSha256']==res['htmlSha256']==H(body) and r['textSha256']==res['retainedTextSha256']==law['retainedTextSha256'];assert r['sourceTreeSha256']==law['sourceTreeSha256'] and r['sourceLeafSequenceSha256']==law['sourceLeafSequenceSha256'] and r['retainedLeafSequenceSha256']==law['retainedLeafSequenceSha256']
  assert len(r['omissions'])==res['omissions'] and r['sourceLeafCount']==law['sourceLeafCount'] and r['retainedLeafCount']==law['retainedLeafCount'] and r['sourceNodeCount']==law['sourceNodeCount']
  findings=[]
  if any(x['text'].startswith('原データ属性 SupplProvision:') for x in r['annotations']):findings.append(SUPPL)
  if any(x['kind']=='official-main-excerpt' for x in r['issues']):findings.append(EXCERPT)
